window.MONSTER_CHUNK_55 = [{"name":"Elephant","cr":7,"xp":3200,"alignment":"N","size":"Huge","type":"animal","init":0,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":17,"ac_touch":8,"ac_flat_footed":17,"ac_mods":"+9 natural, -2 size","hp":93,"hd":"11d8+44","hdvalue":11,"fort":13,"ref":7,"will":6,"speed":[{"type":"land","speed":40}],"melee":"gore +16 (2d8+10), slam +16 (2d6+10)","space":"15 ft.","reach":"10 ft.","special_attacks":[{"type":"trample","details":"2d8+15; DC 25"}],"strength":30,"dexterity":10,"constitution":19,"intelligence":2,"wisdom":13,"charisma":7,"baseatk":8,"cmb":20,"cmd":30,"cmd_special":"+4 vs. trip","feats":[{"feat":"Endurance"},{"feat":"Great Fortitude"},{"feat":"Improved Bull Rush"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Perception","value":21}],"environments":["warm plains"],"organizations":["solitary","herd (6-30)"],"treasure":"none","description_visual":"These thick-skinned animals bear large ivory tusks flanking a long, prehensile snout.","source":"PFRPG Bestiary","description":"These large land animals, majestically wandering the plains in tightly knit family herds, are symbols of wisdom and strength. Having few natural predators, elephants are sometimes hunted for their ivory tusks. These tusks often become jewelry, statuettes, and trinkets for the wealthy.","ecology":"","habitat_society":""},{"name":"Embalming Bear","cr":7,"xp":3200,"alignment":"N","size":"Large","type":"construct","init":-1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":20,"ac_touch":8,"ac_flat_footed":20,"ac_mods":"-1 Dex, +12 natural, -1 size","hp":74,"hd":"8d10+30","hdvalue":8,"fort":2,"ref":1,"will":2,"defensive_abilities":["hardness 5"],"immunities":["construct traits"],"speed":[{"type":"land","speed":30}],"melee":"2 claws +13 (1d8+6 plus grab and poison)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"constrict","details":"1d8+6"}],"strength":22,"dexterity":8,"wisdom":11,"charisma":1,"baseatk":8,"cmb":15,"cmd":24,"cmd_special":"+4 vs. trip","environments":["any"],"organizations":["solitary","pair"],"treasure":"none","description_visual":"This decaying taxidermic bear is held together with thick stitches, metal armor plates, and a pungent chemical fluid.","source":"Tears At Bitter Manor","special_abilities":[{"type":"Poison","kind":"Ex","details":"Potent embalming fluid: Claw-injury; save Fort DC 17; frequency 1/round for 6 rounds; effect 1d2 Dex and 1d2 Con; cure 2 consecutive saves."}],"description":"Though embalming bears could easily be mistaken for beasts brought back from the dead, these strange constructs are actually taxidermic bear corpses that have been modified so they can walk once again. Embalming bears employed as guardians are designed to deliver dangerous doses of embalming fluid with strikes from their powerful claws. Few of these creatures exist, and those that do are found where alchemy is widely practiced or where mummification of pets and guardians is a part of funereal tradition. Embalming bears are often created to guard over precious treasures, but some serve less significant functions, and are merely trophies preserved by taxidermists and animated to decorate macabre halls or guard remote locations.\n\nAn embalming bear is different from other animated objects in that the process of its creation includes a step that turns the chemicals that preserve the taxidermic animal into a weapon. This especially powerful embalming fluid is a deadly poison when injected into the injuries of living enemies. The main purpose of the liquid, though, is to provide the bear with a semifluid mobility normally not afforded to animated objects.\n\nMany embalming bears (such as the one described here) have armor plates bolted onto their bodies, typically disguised as pieces of ceremonial armor to make the creature look as if it had been used in battle. Though this is often just an affectation, some embalming bears actually are honored creatures that died in battle and were then turned into eternal servants. A typical embalming bear is 7 ft. tall and weighs 300 pounds.\n\nConstruction\n\nThe bear carcass, taxidermy process, and armor for an embalming bear cost 900 gp in raw materials alone. In addition, the construct must be injected with 1,200 gp worth of special embalming fluid.\n\nEMBALMING BEAR\n\nCL 8th; Price 18,500 gp\n\nConstruction\n\nRequirements Craft Construct, animate objects, minor creation, creator must be caster level 8th; Skill Craft (taxidermy) DC 18; Cost 10,300 gp","ecology":"","habitat_society":""},{"name":"Ephemeral Echo","cr":7,"xp":3200,"alignment":"NE","size":"Medium","type":"undead","subtypes":["incorporeal"],"init":7,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":20,"ac_touch":20,"ac_flat_footed":16,"ac_mods":"+6 deflection, +3 Dex, +1 dodge","hp":84,"hd":"8d8+48","hdvalue":8,"fort":8,"ref":5,"will":7,"defensive_abilities":["channel resistance +4","incorporeal","rejuvenation"],"immunities":["undead traits"],"speed":[{"type":"land","speed":30,"special":"while corporeal"},{"type":"fly","speed":30,"maneuverability":"perfect"}],"melee":"incorporeal touch +9 (1d6 cold plus 1d4 Charisma damage) or   2 slams +13 (1d6+6) (while corporeal)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bewitching gaze"}],"dexterity":16,"intelligence":11,"wisdom":13,"charisma":22,"baseatk":6,"cmb":9,"cmb_special":"+3 while corporeal","cmd":26,"cmd_special":"+6 while corporeal","feats":[{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Mobility"},{"feat":"Weapon Focus (slam)"}],"skills":[{"skill":"Fly","value":20},{"skill":"Intimidate","value":14},{"skill":"Perception","value":12},{"skill":"Sense Motive","value":10},{"skill":"Stealth","value":21}],"languages":["Common"],"sq":[{"type":"corporeal form"},{"type":"stolen power"}],"environments":["any"],"organizations":["solitary"],"treasure":"none","description_visual":"This ghostly image of a sad-eyed young woman hovers suspended in the air. Her face never loses its mournful expression.","source":"Tears At Bitter Manor","special_abilities":[{"type":"Bewitching Gaze","kind":"Su","details":"1 point of Charisma drain, 30 ft., Fortitude DC 20 negates. The save DC is Charisma-based."},{"type":"Corporeal Form","kind":"Su","details":"Whenever an ephemeral echo deals Charisma damage to a creature, it absorbs a portion of its victim's anguish and becomes more real. It loses the incorporeal subtype and gains a Strength score equal to its Charisma score. Its deflection bonus to AC becomes a natural armor bonus, and its incorporeal touch attack is replaced with two slam attacks. The ephemeral echo loses its fly speed and gains a land speed of 30 ft. These changes last for 1d4 rounds or until the ephemeral echo takes any Charisma damage, whichever comes first. The third time in a day an ephemeral echo deals Charisma damage, its corporeal form lasts for 24 hours or until it takes Charisma damage, whichever comes first."},{"type":"Rejuvenation","kind":"Su","details":"Each ephemeral echo is tied to a unique fetter-some event, location, or object that reminds it of the sadness of its former life. Resolving this fetter (by consecrating the location or destroying the item, for example) destroys the ephemeral echo permanently. If the echo is physically injured or killed but its fetter remains unresolved, the echo rejuvenates fully in 1d10 days."},{"type":"Stolen Power","kind":"Su","details":"Whenever an ephemeral echo deals Charisma damage or drain, it gains a +2 profane bonus on attack rolls, damage rolls, saving throws, skill checks, and ability checks until the end of its next turn. The echo also gains 5 temporary hit points that last for 1 hour."}],"description":"Miserable remnants of souls who died in despair, ephemeral echoes are restless spirits who felt powerless or heartbroken at the moment of their death. They roam the Material Plane, lingering near a fetter they recognize as meaningful to them in life or death. Ephemeral echoes gain power and become corporeal as they sap the strength of personality from their victims, until their incorporeal menace becomes a dangerously tangible threat.\n\nEphemeral echoes exhibit a combination of jealousy and hatred for the living, whom they see as unfairly blessed with the continuation of their lives and potential. They generally attack those who demonstrate a particularly vibrant personality. Upon borrowing their victims' will to take material shape, ephemeral echoes savagely attack the living in a flurry of brutal blows and violent sobs.","ecology":"","habitat_society":""},{"name":"Flesh Golem","cr":7,"xp":3200,"alignment":"N","size":"Large","type":"construct","init":-1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":20,"ac_touch":8,"ac_flat_footed":20,"ac_mods":"-1 Dex, +12 natural, -1 size","hp":79,"hd":"9d10+30","hdvalue":9,"fort":3,"ref":2,"will":3,"dr":"5/adamantine","immunities":["construct traits","magic"],"speed":[{"type":"land","speed":30}],"melee":"2 slams +13 (2d8+5)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"berserk"}],"strength":20,"dexterity":9,"wisdom":11,"charisma":1,"baseatk":9,"cmb":15,"cmd":24,"languages":["none"],"environments":["any"],"organizations":["solitary","gang (2-4)"],"treasure":"none","description_visual":"A hideous monstrosity crafted from body parts stitched together with thick string, wire, and metal staples lurches to horrific life.","group":"Golem","source":"PFRPG Bestiary","special_abilities":[{"type":"Berserk","kind":"Ex","details":"When a flesh golem enters combat, there is a cumulative 1% chance each round that its elemental spirit breaks free and the golem goes berserk. The uncontrolled golem goes on a rampage, attacking the nearest living creature or smashing some object smaller than itself if no creature is within reach, then moving on to spread more destruction. The golem's creator, if within 60 ft., can try to regain control by speaking firmly and persuasively to the golem, which requires a DC 19 Charisma check. It takes 1 minute of inactivity by the golem to reset the golem's berserk chance to 0%."},{"type":"Immunity to Magic","kind":"Ex","details":"A flesh golem is immune to any spell or spell-like ability that allows spell resistance. In addition, certain spells and effects function differently against the creature, as noted below. • A magical attack that deals cold or fire damage slows a flesh golem (as the slow spell) for 2d6 rounds (no save). • A magical attack that deals electricity damage breaks any slow effect on the golem and heals 1 point of damage for every 3 points of damage the attack would otherwise deal. If the amount of healing would cause the golem to exceed its full normal hit points, it gains any excess as temporary hit points. A flesh golem gets no saving throw against attacks that deal electricity damage."}],"description":"A flesh golem is a ghoulish collection of stolen humanoid body parts, stitched together into a single composite form. Its cadaverous flesh has a sickly green or yellowish tint. A flesh golem wears whatever clothing its creator desires, usually just a ragged pair of trousers. It has no possessions and no weapons. A flesh golem stands 8 ft. tall and weighs 500 pounds.\n\nA flesh golem cannot speak, although it can emit a hoarse roar of sorts. It walks and moves with a stiffjointed gait, as if not in complete control of its body.\n\nAlthough most flesh golems are mindless, there are persistent rumors of unusual golems who somehow retain the memories of a previous life. The head (and thus brain) of such flesh golems must be just the right combination of fresh and (in its previous life) strong-willed, and even then luck and chance during the golem's creation seem just as important in retaining the creature's mind.\n\nCertainly most who construct flesh golems prefer mindless slaves over free-willed creations, and as a result intelligent flesh golems are rare indeed.\n\nConstruction The pieces of a flesh golem must come from normal humanoid corpses that have not decayed significantly. Assembly requires a minimum of six different bodies-one for each limb, the torso (including head), and the brain. In some cases, more bodies may be necessary. Special unguents and bindings worth 500 gp are also required.\n\nNote that creating a flesh golem requires casting a spell with the evil descriptor.\n\nFlesh Golem CL 8th; Price 20,500 gp Construction Requirements Craft Construct, animate dead, bull's strength, geas/quest, limited wish, creator must be caster level 8th; Skill Craft (leather) or Heal DC 13; Cost 10,500 gp","ecology":"","habitat_society":""},{"name":"Formian Taskmaster","cr":7,"xp":3200,"alignment":"LN","size":"Medium","type":"monstrous humanoid","init":2,"init_special":"+6 with hive mind","senses":[{"type":"blindsight","modifier":"30 ft."},{"type":"darkvision","modifier":"60 ft."},{"type":"hive mind"}],"ac":20,"ac_touch":12,"ac_flat_footed":18,"ac_mods":"+2 Dex, +8 natural","hp":85,"hd":"10d10+30","hdvalue":10,"fort":6,"ref":9,"will":10,"resists":[{"type":"sonic","value":10}],"speed":[{"type":"land","speed":40}],"melee":"sting +13 (1d4+3 plus poison), 2 claws +13 (1d4+3)","ranged":"dart +12 (1d4+3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"poison"}],"spell_like_abilities_caster_level":10,"spell_like_abilities_concentration":17,"spell_like_abilities":[{"frequency":"3/day","spells":[{"spell":"detect thoughts"},{"spell":"sending","details":"to the hive queen only"}]}],"spellsknown_caster":"bard","spellsknown_caster_level":7,"spellsknown_concentration":14,"spellsknown":[{"spell_level":3,"spell_slots":2,"spells":[{"spell":"confusion"},{"spell":"good hope"}]},{"spell_level":2,"spell_slots":4,"spells":[{"spell":"heroism"},{"spell":"invisibility"},{"spell":"sound burst"},{"spell":"suggestion"}]},{"spell_level":1,"spell_slots":5,"spells":[{"spell":"charm person"},{"spell":"comprehend languages"},{"spell":"cure light wounds"},{"spell":"hideous laughter"},{"spell":"silent image"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"dancing lights"},{"spell":"daze"},{"spell":"detect magic"},{"spell":"mending"},{"spell":"message"},{"spell":"prestidigitation"}]}],"strength":17,"dexterity":14,"constitution":16,"intelligence":13,"wisdom":16,"charisma":19,"baseatk":10,"cmb":13,"cmd":26,"cmd_special":"+4 vs. trip","feats":[{"feat":"Combat Casting"},{"feat":"Point-Blank Shot"},{"feat":"Quick Draw"},{"feat":"Rapid Shot"},{"feat":"Spell Focus (enchantment)"}],"skills":[{"skill":"Appraise","value":6},{"skill":"Bluff","value":9},{"skill":"Climb","value":11},{"skill":"Craft (armor)","value":9},{"skill":"Diplomacy","value":14},{"skill":"Perception","value":16,"special":"+20 with hive mind"},{"skill":"Sense Motive","value":8},{"skill":"Spellcraft","value":6}],"languages":["Common","telepathy 120 ft."],"sq":[{"type":"formian traits"},{"type":"mental motivator","details":"20 rounds/day"}],"environments":["temperate land","any underground","warm land"],"organizations":["solitary","work crew (1 plus 6-12 workers)","band (1 plus 3-15 workers and 5-8 warriors)","embassy (2-6)"],"treasure":"standard (10 darts)","description_visual":"This centaurlike creature is equipped with an ant's mandibles and antennae.","group":"Formian","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Mental Motivator","kind":"Su","details":"A formian taskmaster can inspire competence or inspire courage as a 7th-level bard (typically 20 rounds/day). The taskmaster's performance is purely mental and only affects formians from its own hive within telepathic range."},{"type":"Poison","kind":"Ex","details":"Sting-injury; save Fort DC 18; frequency 1/round for 6 rounds; effect 1d4 Dexterity; cure 2 consecutive saves. Spells A formian taskmaster casts spells as a 7th-level bard. It favors enchantment and illusion spells."}],"description":"Formian taskmasters are merchants, traders, diplomats, and spies, and particularly talented taskmasters may even advise the queen. Taskmasters can often be found outside the hive engaging in commerce or routine diplomatic missions. While traveling, a taskmaster is usually accompanied by 3-5 workers and at least 5 warriors. When dealing with other creatures, formians recognize that their telepathy can be off-putting and use normal speech, although their mandibles are not well suited for the task and their voices are often hoarse and diff icult to understand. Like myrmarchs, taskmasters are highly competitive and take great pride in their successes. Notable accomplishments are carved into their carapaces and highlighted with the use of bright inks, precious metals, or gems. Formian society is largely free of the crime that is common in other humanoid societies, but formians do have occasional duels within a caste. Two taskmasters might have a duel over promotions, a trade route, or an insult. These duels are rarely lethal for fear of weakening the hive, and taskmasters who are too aggressive attract the wrong kind of attention from the myrmarchs. Dueling victories are often recorded on taskmasters' carapaces alongside their other major accomplishments.","ecology":"","habitat_society":""},{"name":"Frost Drake","cr":7,"xp":3200,"alignment":"CE","size":"Large","type":"dragon","subtypes":["cold"],"init":5,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"},{"type":"snow vision"}],"ac":20,"ac_touch":10,"ac_flat_footed":19,"ac_mods":"+1 Dex, +10 natural, -1 size","hp":84,"hd":"8d12+32","hdvalue":8,"fort":10,"ref":7,"will":5,"immunities":["cold","paralysis","sleep"],"weaknesses":["vulnerability to fire"],"speed":[{"type":"land","speed":20},{"type":"burrow","speed":20,"special":"snow only"},{"type":"fly","speed":60,"maneuverability":"average"}],"melee":"bite +13 (2d6+6 plus 1d6 cold), tail slap +8 (1d8+3)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"freezing mist breath"}],"strength":22,"dexterity":13,"constitution":18,"intelligence":8,"wisdom":9,"charisma":13,"baseatk":8,"cmb":15,"cmd":26,"feats":[{"feat":"Flyby Attack"},{"feat":"Improved Initiative"},{"feat":"Power Attack"},{"feat":"Vital Strike"}],"skills":[{"skill":"Climb","value":17},{"skill":"Fly","value":10},{"skill":"Intimidate","value":12},{"skill":"Perception","value":10},{"skill":"Stealth","value":8}],"languages":["Draconic"],"sq":[{"type":"speed surge"},{"type":"icewalking"}],"environments":["cold mountains"],"organizations":["solitary","pair","rampage (3-12)"],"treasure":"standard","description_visual":"This two-legged dragon has dull blue scales tinged with bright blue ice. A freezing mist issues from between its powerful jaws.","group":"Drake","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Freezing Mist Breath","kind":"Su","details":"A frost drake can, as a standard action, spit a ball of liquid that bursts into a cloud of freezing mist. This attack has a range of 60 ft. and deals 7d6 points of cold damage (DC 18 Reflex half) to all creatures in a 20-foot-radius spread. The mist cakes all surfaces in the area with a sheet of slippery ice that turns the area into difficult terrain for 2d4 rounds, after which the ice cracks or melts enough to revert to the normal terrain features in the area. Once a frost drake has used its freezing mist breath, it cannot do so again for 1d6 rounds. The Reflex save is Constitution-based."},{"type":"Icewalking","kind":"Ex","details":"This ability works like spider climb, but the surfaces the drake climbs must be icy. It can move across icy surfaces without penalty and doesn't need to make Acrobatics checks to run or charge on ice."},{"type":"Speed Surge","kind":"Ex","details":"Three times per day as a swift action, a frost drake may draw on its draconic heritage for a boost of strength and speed to take an additional move action in that round."},{"type":"Snow Vision","kind":"Ex","details":"A frost drake can see perfectly well in snowy conditions, and doesn't take any penalties on Perception checks while in snow."}],"description":"Degenerate cousins of white dragons, frost dragons are ferocious predators. They are larger than other drakes, reaching heights of up to 16 ft. and weighing upward of 2,500 pounds. Their wide, clawed ft. enable them to easily burrow through snow, though not through dirt or clay.\n\nYoung frost drakes form adolescent hunting packs divided along gender lines, but older frost drakes are usually encountered in mated pairs. Frost drakes mate for life, leaving their packs when they find a suitable mate.\n\nMated pairs make a nest together, and the female lays a clutch of two to five eggs. Both parents care for their offspring when they hatch, and families usually form small packs until the young reach maturity at 5 years of age. At this point, the parents abandon their offspring, usually laying a new clutch of eggs in a new nest elsewhere, and leaving the fledgling drakes to find their own adolescent packs to join.","ecology":"","habitat_society":""},{"name":"Gaki","cr":7,"xp":3200,"alignment":"NE","size":"Medium","type":"undead","init":6,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"detect evil"}],"ac":20,"ac_touch":13,"ac_flat_footed":17,"ac_mods":"+2 Dex, +1 dodge, +7 natural","hp":74,"hd":"9d8+32","hdvalue":9,"fort":5,"ref":7,"will":9,"immunities":["undead traits"],"weaknesses":["aversion to sun and moon","compulsive hunger","vulnerable to cold and fire"],"speed":[{"type":"land","speed":30},{"type":"fly","speed":30,"maneuverability":"average"}],"melee":"2 claws +9 (2d6+3), bite +9 (2d6+3 plus grab)","space":"5 ft.","reach":"5 ft. (10 ft. with bite)","special_attacks":[{"type":"blood drain","details":"1d2 Constitution"},{"type":"fear cone","details":"30 ft., DC 16"}],"spell_like_abilities_caster_level":7,"spell_like_abilities_concentration":7,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect evil"}]},{"frequency":"at-will","spells":[{"spell":"invisibility"}]},{"frequency":"1/day","spells":[{"spell":"disguise self"}]}],"strength":16,"dexterity":15,"intelligence":9,"wisdom":12,"charisma":18,"baseatk":6,"cmb":9,"cmb_special":"+4 vs. grapple","cmd":22,"feats":[{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"}],"skills":[{"skill":"Intimidate","value":14},{"skill":"Perception","value":13},{"skill":"Stealth","value":14}],"languages":["Common"],"environments":["any land"],"organizations":["solitary","gang (2-4)"],"treasure":"incidental","description_visual":"This skeletal creature with a long, thin neck seems to float above the ground. Its jaw is elongated, showing sharp, worn teeth.","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Aversion to Sun and Moon","kind":"Ex","details":"A gaki takes 1d4 points of fire damage every round it's exposed to the light of a full moon. It takes 1d4 points of cold damage every round it is exposed to direct sunlight."},{"type":"Compulsive Hunger","kind":"Ex","details":"Despite being undead, a gaki is plagued by an insatiable hunger, and believes it can gain a normal body or rest in peace if it consumes the right mixture of flesh, food, and drink. A gaki that finds a corpse or is offered food, wine, holy water, or flowers must succeed at a DC 20 Will save or spend one turn trying to grab and consume it. Its narrow neck prevents it from swallowing more than a tiny amount, and it gives up after 1 round of attempting to do so. A gaki that consumes holy water in this way isn't harmed by it."}],"description":"When an especially jealous or greedy evil person dies, it sometimes returns as a gaki-a misshapen creature with a supernatural hunger for things of the material world. Mistakenly called \"hungry ghosts\" because of their ability to fly and turn invisible, gakis believe that if they consume the right material-typically meat, wine, blood, flowers, and souls-they can form a new body resembling their former mortal shapes. Its long, thin neck restricts how much it can eat, and the creature is perpetually starving. It prefers to consume evil creatures, believing it gains more sustenance from a sinful being than a righteous one, but it won't pass up any mortal flesh. Some gakis believe they must consume flesh from demons or undead, and fixate on these creatures to the aversion of all others. Gakis are cursed, pitiable creatures with nothing to lose, which makes them very dangerous. Some that have existed for many years as undead grow desperate and try consuming earth, sewage, or more vile substances in an attempt to find the missing ingredient for their transformation. Particularly unfortunate ones bear an onerous curse that causes anything they try to eat to burst into flame or wither away into dust. These creatures have short memories and little sense of perspective. They're smart enough to pursue what they want cannily, but fail at making long-term plans. Most gakis wander alone, pursuing their search for nourishment in solitude. When they do form packs, they use their numbers to surround and bring down large animals or groups of people, but then throw cooperation aside to squabble and shove as each one greedily tries to claim the entire prize they've taken. Strangely, gakis are scorched by moonlight and frozen by sunlight. Because of this, they're forced to lurk in the shadows of ruins. Some wander the deep caves and tunnels below the surface, scrounging whatever meals they can find. In urban areas, they group together to stalk the slums, often leaping upon victims, tearing away small morsels of flesh before they retreat, leaving victims bleeding and disoriented. They find hiding places- often in abandoned buildings or sewers- to stay during the day, turning invisible and biding their time till the dark of night comes.","ecology":"","habitat_society":""},{"name":"Ghost","cr":7,"xp":3200,"race":"Human ghost","classes":[{"class":"aristocrat","level":7}],"alignment":"CE","size":"Medium","type":"undead","subtypes":["augmented humanoid","incorporeal"],"init":5,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":17,"ac_touch":17,"ac_flat_footed":15,"ac_mods":"+1 Dex, +1 dodge, +5 deflection","hp":73,"hd":"7d8+42","hdvalue":7,"fort":7,"ref":5,"will":7,"defensive_abilities":["channel resistance +4","incorporeal","rejuvenation"],"immunities":["undead traits"],"speed":[{"type":"fly","speed":30,"maneuverability":"perfect"}],"melee":"corrupting touch +6 (7d6, Fort. DC 18 half)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"frightful moan","details":"DC 18"}],"dexterity":12,"intelligence":10,"wisdom":11,"charisma":20,"baseatk":5,"cmb":5,"cmd":22,"feats":[{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Toughness"}],"skills":[{"skill":"Fly","value":9},{"skill":"Knowledge (history)","value":10},{"skill":"Knowledge (nobility)","value":10},{"skill":"Perception","value":18},{"skill":"Sense Motive","value":10},{"skill":"Stealth","value":9}],"languages":["Common"],"environments":["any"],"organizations":["solitary"],"treasure":"none","description_visual":"This spectral, horrifying figure glides silently through the air, passing through solid objects as if they didn't exist.","source":"PFRPG Bestiary","description":"When a soul isn't allowed to rest due to some great injustice, either real or perceived, it sometimes comes back as a ghost. Such beings are in eternal anguish, lacking in substance and unable to set things right. Although ghosts can be any alignment, the majority cling to the living world out of a powerful sense of rage and hatred, and as a result are chaotic evil-even the ghost of a good or lawful creature can become hateful and cruel in its afterlife. More than most of the monsters in this book, a ghost benefits from a strong and detailed backstory. Why did this character become a ghost? What are the legends surrounding the ghost? An encounter with a ghost should never happen completely out of the blue-there are plenty of other incorporeal undead like wraiths and spectres to fill that role. A proper encounter with a ghost should be a climactic scene after a lengthy period of tension building with lesser minions or manifestations of the undead spirit. The sample ghost above is that of a human princess who was murdered by an unfaithful lover-after she confronted him, he murdered her by wrapping her in chains and throwing her into the castle well, where she drowned. The ghost's abilities were selected to fit this backstory, and it shows how potent a villain you can create with a simple NPC class. Applying the template to creatures with class levels or creatures with significant racial abilities can create even more powerful ghosts. When a ghost is created, it retains incorporeal \"copies\" of any items that it particularly valued in life (provided the originals are not in another creature's possession). The equipment works normally for the ghost but passes harmlessly through material objects or creatures. A weapon of +1 or better magical enhancement, however, can harm material creatures, but any such attack deals only half as much damage (50%) unless it is a ghost touch weapon. A ghost can use shields or armor only if they have the ghost touch quality. The original items remain behind, just as the ghost's physical remains do. If another creature seizes the original, the incorporeal copy fades away. This loss invariably angers the ghost, who stops at nothing to return the item to its original resting place (and thus regain the item's use).","ecology":"","habitat_society":""},{"name":"Giant Jellyfish","cr":7,"xp":3200,"alignment":"N","size":"Large","type":"vermin","subtypes":["aquatic"],"init":2,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":11,"ac_touch":11,"ac_flat_footed":9,"ac_mods":"+2 Dex, -1 size","hp":94,"hd":"9d8+54","hdvalue":9,"fort":12,"ref":5,"will":3,"defensive_abilities":["amorphous"],"dr":"10/ piercing or slashing","immunities":["mindaffecting effects"],"speed":[{"type":"swim","speed":20}],"melee":"4 tentacles +9 (1d6+4 plus poison)","space":"10 ft.","reach":"15 ft.","strength":18,"dexterity":15,"constitution":22,"wisdom":11,"charisma":1,"baseatk":6,"cmb":11,"cmd":23,"cmd_special":"can't be tripped","skills":[{"skill":"Swim","value":12}],"sq":[{"type":"compression"}],"environments":["any oceans"],"organizations":["solitary","pack (2-5)","bloom (6-12)"],"treasure":"None","description_visual":"The bell of this enormous amber jellyfish is as large as a carriage. A sinister bloom of tentacles dangles and writhes below.","group":"Jellyfish","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Poison","kind":"Ex","details":"Tentacles-injury; save Fort DC 17; frequency 1/round for 6 rounds; effect 1d4 Con; cure 2 consecutive saves. The save DC is Constitution based."}],"description":"Unlike its smaller cousins, the giant jellyfish is an active predator that seeks out prey. Capable of slithering through narrow cracks, a giant jellyfish is a horrifying beast to encounter lurking in the hold of a flooded or sunken ship. Other species of these vermin exist, as summarized on the following table-these variants often have different types of poison or other abilities like translucency or constriction. Species CR Size HD Death's head jellyfish 1 Small 2 Crimson jellyfish 4 Medium 5 Sapphire jellyfish 11 Huge 12 Vampire jellyfish 14 Gargantuan 16 Whaler jellyfish 17 Colossal 20.","ecology":"","habitat_society":""},{"name":"Giant Sea Snake","cr":7,"xp":3200,"alignment":"N","size":"Huge","type":"animal","init":6,"senses":[{"type":"low-light vision"}],"ac":20,"ac_touch":10,"ac_flat_footed":18,"ac_mods":"+2 Dex, +10 natural, -2 size","hp":85,"hd":"9d8+45","hdvalue":9,"fort":11,"ref":10,"will":5,"speed":[{"type":"land","speed":30},{"type":"climb","speed":20},{"type":"swim","speed":40}],"melee":"bite +14 (2d8+13/19- 20 plus poison)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"poison"}],"strength":29,"dexterity":14,"constitution":20,"intelligence":1,"wisdom":15,"charisma":2,"baseatk":6,"cmb":17,"cmd":29,"feats":[{"feat":"Improved Critical (bite)"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Snatch"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Climb","value":17},{"skill":"Perception","value":12},{"skill":"Stealth","value":7},{"skill":"Swim","value":17}],"sq":[{"type":"hold breath"}],"environments":["warm oceans"],"organizations":["solitary","pair"],"treasure":"none","description_visual":"This great, writhing aquatic beast is pale blue with bright yellow stripes, and possesses a flipperlike tail to aid it as it swims.","group":"Sea Snake","source":"Isles Of The Shackles","special_abilities":[{"type":"Poison","kind":"Ex","details":"Bite-injury; save Fort DC 19; frequency 1/round for 6 rounds; effect 1d2 Dex and 1d2 Con; cure 2 consecutive saves."}],"description":"The giant sea snake is one of the biggest reasons many sailors of the Shackles have a downright visceral and phobic response to the thought of falling overboard. These patient predators are known to follow sailing ships, swimming just below the surface of the water while they wait for the opportunity to strike at any unfortunate crew members who might fall over the side. Particularly hungry giant sea snakes have been known to climb the side of a vessel and snatch unwary sailors right from the deck.\n\nGiant sea snakes typically reach up to 30 ft. in length and weigh 500 pounds.","ecology":"","habitat_society":""},{"name":"Gorthek","cr":7,"xp":3200,"alignment":"N","size":"Large","type":"animal","init":-1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":18,"ac_touch":8,"ac_flat_footed":18,"ac_mods":"-1 Dex, +10 natural, -1 size","hp":85,"hd":"9d8+45","hdvalue":9,"fort":13,"ref":5,"will":3,"dr":"5/-","speed":[{"type":"land","speed":40}],"melee":"gore +16 (2d6+16)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"powerful charge","details":"gore, 4d6+22"},{"type":"trample","details":"2d6+16, DC 25"}],"strength":32,"dexterity":9,"constitution":21,"intelligence":2,"wisdom":10,"charisma":5,"baseatk":6,"cmb":18,"cmb_special":"+2 vs. bull rush or sunder","cmd":27,"cmd_special":"+2 vs. bull rush or sunder, +4 vs. trip","feats":[{"feat":"Awesome Blow"},{"feat":"Great Fortitude"},{"feat":"Improved Bull Rush"},{"feat":"Improved Sunder"},{"feat":"Power Attack"}],"skills":[{"skill":"Perception","value":12}],"environments":["temperate hills","temperate plains"],"organizations":["solitary","pair","herd (3-12)"],"treasure":"none","description_visual":"This massive quadruped has a thick, wrinkled hide, curving horns, and shaggy hair that frames its leonine face.","source":"Monster Codex","description":"The gorthek is, without a doubt, one of the crankiest beasts found roaming in the wilderness. Appearing as a strange combination of primeval bison and ornery rhinoceros, but with a leonine head crowned with ramlike horns, a gorthek is both immensely powerful and preternaturally hard to injure. Its thick, battering-ram head and powerful body make it a fearsome opponent, particularly when it's riled up and in full charge.\n\nGortheks tend to travel in small herds, grazing across remote temperate grasslands or sparsely wooded hills. When a gorthek perceives a threat-which to the gorthek includes just about everything, often even other gortheks-it launches itself into a full charge, intent on sending the enemy flying.\n\nOrc tribes have made a practice of raising the beasts from infancy to serve as living siege engines during warfare. Future gorthek riders bond with the creatures from a very young age, and if possible use gorthek masks to make that bond stronger. When riding into battle, one orc sits astride the gorthek in a specially crafted saddle secured behind its massive horns and guides the beast using spiked reins.\n\nAn adult male gorthek stands about 7 ft. high at the shoulder and weighs around 9,000 pounds.\n\nGorthek Companions\n\nAn orc who takes the Beast Rider feat can choose a gorthek as an animal companion or mount.\n\nStarting Stats: Size Medium; AC +4 natural armor; Speed 40 ft.; Attack gore (1d8); Ability Scores Str 16, Dex 11, Con 13, Int 2, Wis 10, Cha 5; Special Qualities darkvision 60 ft., low-light vision.\n\n7th-Level Advancement: Size Large; AC +3 natural armor; Attacks gore (2d6) Ability Scores Str +8, Dex -2, Con +4; Special Attacks powerful charge (gore, 4d6 + twice Strength modifier).","ecology":"","habitat_society":""},{"name":"Greater Barghest","cr":7,"xp":3200,"alignment":"LE","size":"Large","type":"outsider","subtypes":["evil","extraplanar","lawful","shapechanger"],"init":6,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"scent"}],"ac":20,"ac_touch":11,"ac_flat_footed":18,"ac_mods":"+2 Dex, +9 natural, -1 size","hp":85,"hd":"9d10+36","hdvalue":9,"fort":9,"ref":10,"will":10,"dr":"10/magic","speed":[{"type":"land","speed":40}],"melee":"bite +14 (1d8+6), 2 claws +14 (1d6+6)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":9,"spell_like_abilities_concentration":17,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"blink"},{"spell":"invisibility sphere"},{"spell":"levitate"},{"spell":"misdirection"}]},{"frequency":"1/day","spells":[{"spell":"charm monster"},{"spell":"crushing despair"},{"spell":"dimension door"},{"spell":"mass bull's strength"},{"spell":"mass enlarge"}]}],"strength":23,"dexterity":15,"constitution":19,"intelligence":18,"wisdom":18,"charisma":18,"baseatk":9,"cmb":16,"cmd":28,"cmd_special":"+4 vs. trip","feats":[{"feat":"Combat Casting"},{"feat":"Combat Reflexes"},{"feat":"Improved Initiative"},{"feat":"Great Fortitude"},{"feat":"Lightning Reflexes"}],"skills":[{"skill":"Acrobatics","value":14},{"skill":"Bluff","value":16},{"skill":"Climb","value":15},{"skill":"Diplomacy","value":16},{"skill":"Intimidate","value":16},{"skill":"Perception","value":16},{"skill":"Sense Motive","value":16},{"skill":"Stealth","value":10},{"skill":"Survival","value":16},{"skill":"Swim","value":15}],"languages":["Common","Goblin","Infernal"],"sq":[{"type":"change shape","details":"goblin or wolf, polymorph"}],"environments":["any"],"organizations":["solitary","cult (1 plus goblin tribe)"],"treasure":"standard","description_visual":"This snarling, canine beast pads forward on all fours, its slender front limbs looking more like hands than a wolf 's paws.","group":"Barghest","source":"PFRPG Bestiary","special_abilities":[{"type":"Feed","kind":"Su","details":"Once per month, a barghest can devour a nonevil humanoid's corpse as a full-round action to gain a growth point. It gains a bonus equal to its growth point total on attack rolls, CMB rolls, saving throws, and skill checks. Its maximum hit points increase by 5 for each growth point it gains. For every 2 growth points, a barghest's caster level for its spell-like abilities and its CR increase by +1. When a barghest reaches 4 growth points, it sheds its skin and becomes a greater barghest, losing all of its growth points (and bonuses) but gaining the stats presented on this page for a greater barghest."}],"description":"Said to be fiendish relations of all goblinoid races, the hateful barghests come to the Material Plane to feed. As they consume the bodies of innocents, they grow increasingly powerful. A barghest eventually sheds its skin to transform into a greater barghest, at which point it often seeks out a tribe of goblins or other creatures to rule.","ecology":"","habitat_society":""},{"name":"Halsora","cr":7,"xp":3200,"alignment":"CE","size":"Small","type":"aberration","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":19,"ac_touch":13,"ac_flat_footed":17,"ac_mods":"+2 Dex, +6 natural, +1 size","hp":75,"hd":"10d8+30","hdvalue":10,"fort":6,"ref":5,"will":18,"dr":"5/bludgeoning or slashing","immunities":["acid","disease"],"speed":[{"type":"land","speed":30}],"melee":"2 claws +13 (1d8+4 plus spores)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"acidic tears"},{"type":"sneak attack","details":"+2d6"},{"type":"spores"}],"strength":19,"dexterity":14,"constitution":17,"intelligence":6,"wisdom":11,"charisma":8,"baseatk":7,"cmb":11,"cmd":28,"feats":[{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Skill Focus (Perception)"},{"feat":"Skill Focus (Stealth)"},{"feat":"Weapon Focus (claw)"}],"skills":[{"skill":"Perception","value":19},{"skill":"Stealth","value":25}],"languages":["Undercommon","Vegepygmy (can't speak)"],"environments":["any underground"],"organizations":["solitary","gang (2-6)"],"treasure":"none","description_visual":"This small, plantlike creature is a bulging mass of viselike muscle with sunken eyes that constantly drip viscous, black tears.","group":"Fleshwarp","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Acidic Tears","kind":"Ex","details":"A halsora's sunken eyes have oversized tear ducts that weep a constant stream of black, acidic tears. As a standard action that provokes attacks of opportunity, a halsora can jerk its head and flick the acidic tears on a single creature within 20 ft. That creature takes 2d6 acid damage (Reflex DC 18 half). A creature that fails its save takes an additional 1d4 points of acid damage at the end of the halsora's turn for 1d4 rounds or until the acid is scraped off, which requires a full-round action on the part of the creature taking the damage or a creature adjacent to that creature. The save DC is Constitution-based."},{"type":"Spores","kind":"Ex","details":"A halsora's claws are covered in mutated russet mold spores. A creature hit by a claw attack must succeed at a DC 18 Fortitude save or take 2 points of Constitution damage per round. It can attempt a new Fortitude save each round to halt the growth. A creature reduced to 0 Constitution by these spores explodes in a mess of viscera and spores. Creatures within the burst must succeed at a DC 18 Fortitude saving throw or be affected as if they were hit by the halsora's claw attack. This is a disease effect. The save is Constitution-based."}],"description":"Vegepygmies transformed by the vile fleshwarping process become halsoras, creatures twice cursed. The alchemical torture they undergo seems minor compared to what other fleshwarps suffer-it merely increases the mass and strength of the vegepygmy and deforms its eyes so they secrete acid. The process has a more interesting effect on the residual and previously inert russet mold within the body of the host vegepygmy. Mutating the mold, it creates a deadly spore that courses through the halsora's insides, is slowly excreted through the fingertips, and clumps on the claws of the creature. Though their sunken eyes and constant stream of acidic tears often make these creatures seem pitiful, they are fierce bundles of rage and self-hatred. The conditioning of the fleshwarpers causes them to attack and infect any enemy of the drow they come in contact with, but what's left of their consciousness rages against the mutated spores they carry. Worse still, many drow use these creatures to hunt down and even infect other tribes of vegepygmies.","ecology":"","habitat_society":""},{"name":"Hangman Tree","cr":7,"xp":3200,"alignment":"NE","size":"Huge","type":"plant","init":3,"senses":[{"type":"blindsight","modifier":"60 ft."}],"ac":20,"ac_touch":7,"ac_flat_footed":20,"ac_mods":"-1 Dex, +13 natural, -2 size","hp":84,"hd":"8d8+48","hdvalue":8,"fort":12,"ref":3,"will":5,"immunities":["plant traits"],"sr":18,"weaknesses":["vulnerable to electricity"],"speed":[{"type":"land","speed":10}],"melee":"3 vines +11 (1d6+7 plus grab and pull)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"constrict","details":"1d6+7"},{"type":"hallucinatory spores"},{"type":"pull","details":"vine, 5 ft."},{"type":"strangle"},{"type":"swallow whole","details":"2d6+7 bludgeoning damage, AC 16, 8 hp"},{"type":"vines"}],"strength":25,"dexterity":8,"constitution":23,"intelligence":7,"wisdom":12,"charisma":10,"baseatk":6,"cmb":15,"cmb_special":"+4 vs. grapple","cmd":24,"feats":[{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Perception","value":11},{"skill":"Stealth","value":-2}],"languages":["Sylvan"],"environments":["temperate forests"],"organizations":["solitary","pair"],"treasure":"standard","description_visual":"This sinister tree looms above a field strewn with bones. Numerous leafy vines, their tips looped into nooses, hang from its branches.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Hallucinatory Spores","kind":"Ex","details":"Once per day as a standard action, a hangman tree can release a cloud of spores in a 50-foot-radius spread. Creatures in the area must make a DC 20 Will save or believe the hangman tree to be a perfectly ordinary tree- or at worst, a treant or some other friendly tree-like creature. An affected creature becomes passive for 2d6 minutes and refuses to attack the hangman tree during this time. An affected creature can attempt a new Will save each round that the tree attacks an ally-if a hallucinating creature is attacked by the tree, it gains a +4 bonus on its Will save to see through the hallucination. This is a mind-affecting compulsion effect. The save DC is Constitution-based."},{"type":"Vines","kind":"Ex","details":"A hangman tree's vines are primary attacks that deal bludgeoning damage. When a hangman tree grapples a foe with its vines, the tree doesn't gain the grappled condition. A hangman tree that uses swallow whole transfers a pinned creature from a vine to inside its trunk."}],"description":"The hangman tree prefers to lie in wait near remote forest tracks and game trails, waiting for victims to wander by. These carnivorous plants are incredibly patient, and can wait for months in a single location for food to approach. When prey does draw near, the tree's vines lash like striking snakes. The tree often uses its pull ability to hoist grappled foes 10 to 15 ft. in the air so that they are out of reach of allies while they slowly strangle. The tree generally only swallows one foe whole at a time, letting its other captured victims dangle and ripen until it is ready to feed on them.\n\nA hangman tree is 30 ft. tall and weighs 12,000 pounds.","ecology":"","habitat_society":""},{"name":"Hellcat","cr":7,"xp":3200,"alignment":"LE","size":"Large","type":"outsider","subtypes":["evil","extraplanar","lawful"],"init":9,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"scent"}],"ac":21,"ac_touch":15,"ac_flat_footed":15,"ac_mods":"+5 Dex, +1 dodge, +6 natural, -1 size","hp":85,"hd":"9d10+36","hdvalue":9,"fort":10,"ref":13,"will":5,"defensive_abilities":["invisible in light"],"dr":"5/good","resists":[{"type":"fire","value":10}],"sr":18,"speed":[{"type":"land","speed":40}],"melee":"bite +13 (1d8+5), 2 claws +13 (1d6+5/19-20 plus grab)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"pounce"},{"type":"rake","details":"2 claws +13, 1d6+5/19-20"}],"strength":21,"dexterity":21,"constitution":19,"intelligence":10,"wisdom":14,"charisma":10,"baseatk":9,"cmb":15,"cmb_special":"+4 vs. grapple","cmd":31,"cmd_special":"+4 vs. trip","feats":[{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Mobility"}],"skills":[{"skill":"Acrobatics","value":17,"special":"+21 jump"},{"skill":"Climb","value":17},{"skill":"Perception","value":18},{"skill":"Stealth","value":17},{"skill":"Survival","value":14},{"skill":"Swim","value":17}],"languages":["Infernal (can't speak)","telepathy 100 ft."],"environments":["any land (Hell)"],"organizations":["solitary","pair","pack (3-8)"],"treasure":"standard","description_visual":"This eerie beast appears to be the animated skeleton of a huge fanged cat, its bones glowing with fire and seething with smoke.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Invisible in Light","kind":"Su","details":"In bright light, a hellcat has natural invisibility. In normal light, a hellcat has partial concealment (20% miss chance). In dim light, it has no concealment. In darkness, a hellcat's flickering glow limits it to partial concealment, unless the darkness is magical in nature."}],"description":"The hellcat is a devious predator native to the fiery pits of Hell. While the hellcat isn't a devil itself, it often acts as a guardian or mount for devils.\n\nSome might assume that hellcats serve devils as pets, but since hellcats are as intelligent as humans, they take offense to the idea that they might be anyone's pet.\n\nOn its own, a hellcat prefers to spend its time hunting and stalking prey. While the hellcat, as an outsider, need not eat to survive, it does enjoy eating for pleasure, often leaving significant portions of its kills behind for others to find. A hellcat that enters into an alliance with a devil is often used as a sort of hunter as a result. Human mortals can use spells like planar ally or planar binding to conjure hellcats for similar purposes. Those who do so are well advised to treat the hellcat with respect, for should any master prove too haughty with his hellcat or treat it as a dumb animal, the hellcat nurtures a lasting grudge. In such instances, the hellcat goes to great lengths to plan and coordinate revenge on the spellcaster, hoping to satisfy its own pride and to provide a lesson and example to all those who would deal with their kind.\n\nThough incapable of speech themselves, hellcats understand the Infernal tongue of their home plane, and can communicate by telepathy with any creature capable of speech. Hellcats are quick to retreat if they are clearly overmatched or up against foes they cannot reach, but they never forget prey that escapes them, and will often track potential victims and try to lead allies (including other hellcats) to them in order to make coordinated attacks or ambushes.\n\nThe hellcat is only clearly visible in dim light, at these times appearing as a skeletal dire tiger with hellish flames burning and flickering along the surface of its bones.\n\nDespite this eerie appearance, the hellcat is neither undead nor an elemental creature. The \"fires\" are actually its blood coursing through transparent flesh. In bright light, the hellcat's entire body fades away into obscurity, while in darkness its glowing blood is muted.\n\nHellcats are as large as tigers, measuring 9 ft. long and weighing 900 pounds.","ecology":"","habitat_society":""},{"name":"Hill Giant","cr":7,"xp":3200,"alignment":"CE","size":"Large","type":"humanoid","subtypes":["giant"],"init":-1,"senses":[{"type":"low-light vision"}],"ac":21,"ac_touch":8,"ac_flat_footed":21,"ac_mods":"+4 armor, -1 Dex, +9 natural, -1 size","hp":85,"hd":"10d8+40","hdvalue":10,"fort":11,"ref":2,"will":3,"defensive_abilities":["rock catching"],"speed":[{"type":"land","speed":30,"special":"40 ft. without armor"}],"melee":"greatclub +14 (2d8+10) or 2 slams +13 (1d8+7)","ranged":"rock +6 (1d8+10)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"rock throwing","details":"120 ft."}],"strength":25,"dexterity":8,"constitution":19,"intelligence":6,"wisdom":10,"charisma":7,"baseatk":7,"cmb":15,"cmd":24,"feats":[{"feat":"Cleave"},{"feat":"Intimidating Prowess"},{"feat":"Martial Weapon Proficiency (greatclub)"},{"feat":"Power Attack"},{"feat":"Weapon Focus (greatclub)"}],"skills":[{"skill":"Climb","value":10},{"skill":"Intimidate","value":12},{"skill":"Perception","value":6}],"languages":["Giant"],"environments":["temperate hills"],"organizations":["solitary","gang (2-5)","band (6-8)","raiding party (9-12 plus 1d4 dire wolves)","tribe (13-30 plus 35% noncombatants plus 1 barbarian or fighter chief of 4th-6th level, 11-16 dire wolves, 1-4 ogres, and 13-20 orc slaves)"],"treasure":"standard (hide armor, greatclub)","description_visual":"This hunched giant exudes power and a crude, stupid anger, its filthy fur clothing bespeaking a brutish and backwoods lifestyle.","group":"Giant","source":"PFRPG Bestiary","description":"Skin color among hill giants ranges from light tan to deep, ruddy brown. Their hair is brown or black, with eyes the same color. Hill giants wear layers of crudely prepared hides with the fur left on. They seldom wash or repair their garments, preferring simply to add more hides as their old ones wear out. Adults are around 10 ft. tall and weigh about 1,100 pounds. Hill giants can live to be 200 years old, but almost never do.\n\nHill giants prefer to fight from high, rocky outcroppings, where they can pelt opponents with rocks and boulders while limiting the risk to themselves. Hill giants love to make overrun attacks against smaller creatures when they first join battle. Thereafter, they stand fast and swing away with their massive clubs.\n\nHill giants are the most nomadic of all the humanoid giant species, preferring to travel from one settlement to the next in order to raid and pillage. While they prefer temperate climates, they'll travel far from their preferred environment so long as the raiding is plentiful and successful. They are, as a whole, incredibly selfish creatures and rarely engage in battles they don't automatically know they'll win. Hill giants are known for shoving one another at terrifying foes and won't hesitate to sacrifice a clanmate to save their own skins. Roving bands of hill giants are common in temperate hills, and their constant aggression makes them one of the more feared dangers in this climate.\n\nSolitary, non-evil hill giants are very rare but can sometimes be found in other humanoid societies, though they are almost never accepted in central cities or population centers. They do best as laborers and soldiers in outlying frontier towns, and often serve as rudimentary diplomats to negotiate with marauding hill giant bands. Unfortunately, hill giants who shed their racial lifestyle for civilization are mocked and often killed on sight by their nomadic brethren. Still, these \"civilized\" hill giants can find their place within society and many have managed to live peaceful, uneventful lives.","ecology":"","habitat_society":""},{"name":"Hound of Tindalos","cr":7,"xp":3200,"alignment":"NE","size":"Medium","type":"outsider","subtypes":["evil","extraplanar"],"init":9,"senses":[{"type":"darkvision","modifier":"120 ft."}],"ac":20,"ac_touch":15,"ac_flat_footed":15,"ac_mods":"+5 Dex, +5 natural","hp":85,"hd":"10d10+30","hdvalue":10,"fort":10,"ref":12,"will":8,"dr":"10/magic","immunities":["mind-affecting effects","poison"],"speed":[{"type":"land","speed":40}],"melee":"bite +15 (2d6+3), 2 claws +15 (1d8+3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"ripping gaze"}],"spell_like_abilities_caster_level":10,"spell_like_abilities_concentration":13,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"air walk"}]},{"frequency":"at-will","spells":[{"spell":"fog cloud"},{"spell":"invisibility"},{"spell":"locate creature"}]},{"frequency":"3/day","spells":[{"spell":"dimensional anchor"},{"spell":"discern location"},{"spell":"greater scrying"},{"spell":"haste"},{"spell":"slow"}]}],"strength":17,"dexterity":21,"constitution":16,"intelligence":16,"wisdom":21,"charisma":16,"baseatk":10,"cmb":13,"cmd":28,"cmd_special":"+4 vs. trip","feats":[{"feat":"Blind-Fight"},{"feat":"Combat Reflexes"},{"feat":"Improved Initiative"},{"feat":"Vital Strike"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":18,"special":"+22 jump"},{"skill":"Intimidate","value":16},{"skill":"Knowledge (arcana)","value":16},{"skill":"Knowledge (geography)","value":13},{"skill":"Knowledge (planes)","value":16},{"skill":"Perception","value":18},{"skill":"Sense Motive","value":18},{"skill":"Stealth","value":18},{"skill":"Survival","value":18}],"languages":["Aklo"],"sq":[{"type":"angled entry"},{"type":"otherworldly mind"}],"environments":["any"],"organizations":["solitary","pack (2-12)"],"treasure":"none","description_visual":"This gaunt, long-limbed quadruped has huge, soulless eyes and a toothy maw. The lean creature moves with a predatory grace.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Angled Entry","kind":"Su","details":"Hounds of Tindalos move through the dimensions in ways other creatures cannot comprehend. They may use greater teleport (self only) once per round as a swift action and plane shift (self only) 3/day as a standard action (caster level 10th). A hound of Tindalos can use these powers anywhere, but its destination point must be adjacent to a fixed angle or corner in the physical environment, such as a wall, floor, or ceiling (as determined by the GM); temporary angles created by cloth, flesh, or small items are not sufficient. It cannot use these abilities to enter curved architecture or open outdoor environments."},{"type":"Otherworldly Mind","kind":"Ex","details":"Any non-outsider attempting to read the thoughts of a hound of Tindalos or communicate with it telepathically takes 5d6 points of nonlethal damage and must make a DC 18 Will save or become confused for 2d4 rounds. This is a mind-affecting effect. The save DC is Charisma-based."},{"type":"Ripping Gaze","kind":"Su","details":"5d6 slashing damage, 30 ft., Fortitude DC 18 negates. A creature that succeeds on its save is immune to that hound's gaze for 24 hours. Damage caused by a ripping gaze can be defeated by damage reduction, but it bypasses DR/magic and slashing. The save DC is Charisma-based."}],"description":"Hounds of Tindalos are otherworldly predators from beyond the bounds of known reality, usually appearing only when summoned by reckless spellcasters. Little is known about their nature outside of blood-spattered notes and deranged writings of the nearly insane survivors of their attacks. Although possessed of great cunning and cruel intellect, the hounds show no evidence of understanding or communicating with mortals. They enter the physical world on their own in pursuit of those who have trodden too much the netherways beyond time and reality-time travelers (be it physical travel or simply divinatory glimpses forward or backward in time) and creatures that teleport without regard to how this movement impacts subtle magical currents in the multiverse particularly draw their interest.","ecology":"","habitat_society":""},{"name":"Huge Air Elemental","cr":7,"xp":3200,"alignment":"N","size":"Huge","type":"outsider","subtypes":["air","elemental","extraplanar"],"init":13,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":22,"ac_touch":18,"ac_flat_footed":12,"ac_mods":"+9 Dex, +1 dodge, +4 natural, -2 size","hp":95,"hd":"10d10+40","hdvalue":10,"fort":11,"ref":16,"will":5,"defensive_abilities":["air mastery"],"dr":"5/-","immunities":["elemental traits"],"speed":[{"type":"fly","speed":100,"maneuverability":"perfect"}],"melee":"2 slams +17 (2d6+6)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"whirlwind","details":"DC 21"}],"strength":22,"dexterity":29,"constitution":18,"intelligence":6,"wisdom":11,"charisma":11,"baseatk":10,"cmb":18,"cmd":38,"feats":[{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Flyby Attack"},{"feat":"Improved Initiative","type":"bonus"},{"feat":"Iron Will"},{"feat":"Mobility"},{"feat":"Weapon Finesse","type":"bonus"}],"skills":[{"skill":"Acrobatics","value":18},{"skill":"Escape Artist","value":18},{"skill":"Fly","value":23},{"skill":"Knowledge (planes)","value":7},{"skill":"Perception","value":13},{"skill":"Stealth","value":9}],"languages":["Auran"],"environments":["any (Plane of Air)"],"organizations":["solitary","pair","gang (3-8)"],"treasure":"none","description_visual":"This cloud-like creature has dark hollows reminiscent of eyes and a mouth, and a howling wind whips it into ominous shapes.","group":"Elemental","source":"PFRPG Bestiary","special_abilities":[{"type":"Air Mastery","kind":"Ex","details":"Airborne creatures take a -1 penalty on attack and damage rolls against an air elemental."}],"description":"Air elementals are fast, flying creatures made of living air. Primitive and territorial, they resent being summoned or doing the bidding of mortals, and much prefer to spend their time on the Plane of Air, swooping and racing through the endless skies. Although all air elementals of a similar size have identical statistics, the exact appearance of an air elemental can vary wildly between individuals. One might be an animated vortex of wind and smoke, while another might be a smoky bird-like creature with glowing eyes and wind for wings. An air elemental prefers to attack flying or otherwise airbone targets, not only because its mastery over flight gives it a slight advantage, but also because it detests the thought of having to touch the ground. An air elemental can move underwater, and although it is an elemental and thus runs no risk of drowning, it has no ranks in Swim and loses much of its speed and mobility when underwater. Whirlwind Whirlwind Elemental Height Weight Save DC Height Small 4 ft. 1 lb. 12 10-20 ft. Medium 8 ft. 2 lbs. 14 10-30 ft. Large 16 ft. 4 lbs. 18 10-40 ft. Huge 32 ft. 8 lbs. 22 10-50 ft. Greater 36 ft. 10 lbs. 23 10-60 ft. Elder 40 ft. 12 lbs. 27 10-60 ft.","ecology":"","habitat_society":""},{"name":"Huge Earth Elemental","cr":7,"xp":3200,"alignment":"N","size":"Huge","type":"outsider","subtypes":["earth","elemental","extraplanar"],"init":-1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"tremorsense","modifier":"60 ft."}],"ac":19,"ac_touch":7,"ac_flat_footed":19,"ac_mods":"-1 Dex, +12 natural, -2 size","hp":95,"hd":"10d10+40","hdvalue":10,"fort":11,"ref":2,"will":7,"dr":"5/-","immunities":["elemental traits"],"speed":[{"type":"land","speed":20},{"type":"burrow","speed":20}],"speed_mod":"earth glide","melee":"2 slams +17 (2d8+9)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"earth mastery"}],"strength":28,"dexterity":8,"constitution":19,"intelligence":6,"wisdom":11,"charisma":11,"baseatk":10,"cmb":21,"cmd":30,"feats":[{"feat":"Awesome Blow"},{"feat":"Cleave"},{"feat":"Greater Bull Rush"},{"feat":"Improved Bull Rush","type":"bonus"},{"feat":"Improved Overrun"},{"feat":"Power Attack"}],"skills":[{"skill":"Appraise","value":6},{"skill":"Climb","value":18},{"skill":"Knowledge (dungeoneering)","value":4},{"skill":"Knowledge (planes)","value":7},{"skill":"Perception","value":13},{"skill":"Stealth","value":4}],"languages":["Terran"],"environments":["any (Plane of Earth)"],"organizations":["solitary","pair","gang (3-8)"],"treasure":"none","description_visual":"This hulking, roughly humanoid creature of dirt and stone explodes up from the earth, faceless save for two glowing gemstone eyes.","group":"Elemental","source":"PFRPG Bestiary","special_abilities":[{"type":"Earth Glide","kind":"Ex","details":"A burrowing earth elemental can pass through stone, dirt, or almost any other sort of earth except metal as easily as a fish swims through water. If protected against fire damage, it can even glide through lava. Its burrowing leaves behind no tunnel or hole, nor does it create any ripple or other sign of its presence. A move earth spell cast on an area containing a burrowing earth elemental flings the elemental back 30 ft., stunning the creature for 1 round unless it succeeds on a DC 15 Fortitude save."},{"type":"Earth Mastery","kind":"Ex","details":"An earth elemental gains a +1 bonus on attack and damage rolls if both it and its foe are touching the ground. If an opponent is airborne or waterborne, the elemental takes a -4 penalty on attack and damage rolls. These modifiers apply to bull rush and overrun maneuvers, whether the elemental is initiating or resisting these kinds of attacks. (These modifiers are not included in the statistics block.)"}],"description":"Earth elementals are plodding, stubborn creatures made of living stone or earth. When utterly still, they resemble a heap of stone or a small hill. When an earth elemental lumbers into action, its actual appearance can vary, although its statistics remain identical to other elementals of its size. Most earth elementals look like terrestrial animals made out of rock, earth, or even crystal, with glowing gemstones for eyes. Larger earth elementals often have a stony humanoid appearance. Bits of vegetation frequently grow in the soil that makes up parts of an earth elemental's body. Elemental Height Weight Small 4 ft. 80 lbs. Medium 8 ft. 750 lbs. Large 16 ft. 6,000 lbs. Huge 32 ft. 48,000 lbs. Greater 36 ft. 54,000 lbs. Elder 40 ft. 60,000 lbs.","ecology":"","habitat_society":""},{"name":"Huge Fire Elemental","cr":7,"xp":3200,"alignment":"N","size":"Huge","type":"outsider","subtypes":["elemental","extraplanar","fire"],"init":11,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":21,"ac_touch":16,"ac_flat_footed":13,"ac_mods":"+7 Dex, +1 dodge, +5 natural, -2 size","hp":85,"hd":"10d10+30","hdvalue":10,"fort":10,"ref":14,"will":5,"dr":"5/-","immunities":["elemental traits","fire"],"weaknesses":["vulnerability to cold"],"speed":[{"type":"land","speed":60}],"melee":"2 slams +15 (2d6+4 plus burn)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"burn","details":"2d6, DC 18"}],"strength":18,"dexterity":25,"constitution":16,"intelligence":6,"wisdom":11,"charisma":11,"baseatk":10,"cmb":16,"cmd":34,"feats":[{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Improved Initiative","type":"bonus"},{"feat":"Iron Will"},{"feat":"Mobility"},{"feat":"Spring Attack"},{"feat":"Weapon Finesse","type":"bonus"}],"skills":[{"skill":"Acrobatics","value":16},{"skill":"Climb","value":13},{"skill":"Escape Artist","value":16},{"skill":"Intimidate","value":9},{"skill":"Knowledge (planes)","value":7},{"skill":"Perception","value":13}],"languages":["Ignan"],"environments":["any (Plane of Fire)"],"organizations":["solitary","pair","gang (3-8)"],"treasure":"none","description_visual":"This creature looks like a living, mobile bonfire, tongues of flame reaching out in search of things to burn.","group":"Elemental","source":"PFRPG Bestiary","description":"Fire elementals are quick, cruel creatures of living flame. They enjoy frightening beings weaker than themselves, and terrorizing any creature they can set on fire. A fire elemental cannot enter water or any other nonf lammable liquid. A body of water is an impassible barrier unless the fire elemental can step or jump over it or the water is covered with a flammable material (such as a layer of oil). Fire elementals vary in appearance-they usually manifest as coiling serpentine forms made of smoke and lame, but some fire elementals take on shapes more akin to humans, demons, or other monsters in order to increase the terror of their sudden appearance. Features on a fire elemental's body are made by darker bits of flame or patches of semi-stable smoke, ash, and cinders. Elemental Height Weight Small 4 ft. 1 lb. Medium 8 ft. 2 lbs. Large 16 ft. 4 lbs. Huge 32 ft. 8 lbs. Greater 36 ft. 10 lbs. Elder 40 ft. 12 lbs.","ecology":"","habitat_society":""}];
